/* ---------- Harness ---------- */
.hnx{padding:12px;display:flex;flex-direction:column;gap:6px}
.hnx-h{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:2px 10px 8px}
.hnx-h>div{display:flex;flex-direction:column}
.hnx-h b{font-weight:500;font-size:13.5px}
.hnx-st{font-size:12px}
.hnx-list{display:flex;flex-direction:column}
.hnx-t{display:flex;align-items:center;gap:12px;padding:8px 10px;border-radius:12px;font-size:13px;transition:background .2s}
.hnx-t:hover{background:var(--wash)}
.hnx-t .ic{width:28px;height:28px;border-radius:9px;display:grid;place-items:center;flex:none;position:relative}
.hnx-t .ic::after{content:"";position:absolute;right:-2px;bottom:-2px;width:8px;height:8px;border-radius:50%;background:var(--ok);box-shadow:0 0 0 2px var(--surface);transition:background .3s}
.hnx-t.off .ic::after{background:var(--faint)}
.hnx-t .ic.brandic{background:var(--surface);box-shadow:inset 0 0 0 1px var(--line);color:var(--fg)}
.hnx-t .ic .brand{width:15px;height:15px}
.hnx-t.err .ic::after{background:var(--bad)}
.hnx-t.chk .ic::after{background:var(--accent);animation:hnp 1s ease-in-out infinite}
@keyframes hnp{50%{transform:scale(1.4);opacity:.5}}
.hnx-t .t{flex:1;min-width:0;display:flex;flex-direction:column}
.hnx-t .t span{font-size:12px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.hnx-t.err .t span{color:var(--bad)}
.hnx-pm{display:grid;grid-template-columns:repeat(3,auto);padding:2px;border-radius:9px;background:var(--chip);position:relative}
.hnx-pm button{position:relative;z-index:1;height:24px;padding:0 8px;font-size:11.5px;color:var(--muted);transition:color .2s}
.hnx-pm button[aria-pressed="true"]{color:var(--fg)}
.hnx-pm .kn{position:absolute;top:2px;bottom:2px;border-radius:7px;background:var(--surface);box-shadow:0 1px 2px rgba(0,0,0,.08);transition:left .4s var(--ease),width .4s var(--ease)}
.hnx-add{display:flex;align-items:center;gap:8px;padding:8px 10px;font-size:12.5px;color:var(--fg2);border-radius:10px;align-self:flex-start}
.hnx-add:hover{color:var(--fg);background:var(--chip)}
.hnx-pop{min-width:220px}

DM.def('harness', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{refresh}', I('refresh','xs')).replace('{plus}', I('plus','xs'));
  let T = [
    ['@figma','Figma','Read and edit frames','var(--pl)',1],
    ['@github','GitHub','designme/web, PRs only','var(--fg)',0],
    ['@slack','Slack','#design, #launch','var(--pm)',1],
    ['db','Analytics','Read only, last 90 days','var(--pt)',1],
    ['globe','Web search','Any public site','var(--pb)',2]
  ];
  const ADD = [['table','Google Sheets','var(--ok)'],['bell','Linear','var(--pp)'],['mail','Gmail','var(--pr)']];
  const list = $('.hnx-list', r), st = $('.hnx-st', r), pop = $('.hnx-pop', r);
  const PM = ['Off','Ask','Allow'];
  function row(t){
    const el = html(`<div class="hnx-t${t[4] === 0 ? ' off' : ''}">${t[0][0] === '@' ? `<span class="ic brandic">${BRAND[t[0].slice(1)]}</span>` : `<span class="ic" style="color:${t[3]};background:color-mix(in srgb,${t[3]} 12%,transparent)">${I(t[0],'xs')}</span>`}<span class="t">${t[1]}<span>${t[2]}</span></span><div class="hnx-pm" role="group" aria-label="${t[1]} permission"><span class="kn"></span>${PM.map((p, i) => `<button aria-pressed="${i === t[4]}" data-tip="${['Agent cannot use it','Agent asks first','Agent uses it freely'][i]}">${p}</button>`).join('')}</div></div>`);
    const g = $('.hnx-pm', el), kn = $('.kn', g), bs = $$('button', g);
    const place = () => { const b = bs[t[4]]; kn.style.left = b.offsetLeft + 'px'; kn.style.width = b.offsetWidth + 'px'; };
    bs.forEach((b, i) => b.onclick = () => { t[4] = i; bs.forEach((x, j) => x.setAttribute('aria-pressed', j === i)); place(); el.classList.toggle('off', i === 0); count(); });
    requestAnimationFrame(place); new ResizeObserver(place).observe(g);
    el._t = t; return el;
  }
  const count = () => swap(st, T.filter(t => t[4] > 0).length + ' connected');
  T.forEach(t => list.appendChild(row(t))); stagger([...list.children], 50); count();
  function menu(){ pop.innerHTML = ADD.length ? ADD.map((a, i) => `<button class="mi" data-close data-i="${i}">${I(a[0],'xs')}<span>${a[1]}</span></button>`).join('') : '<div class="ph" style="padding:8px;font-size:12.5px;color:var(--muted)">All tools connected</div>';
    $$('.mi', pop).forEach(m => m.addEventListener('click', () => { const a = ADD.splice(+m.dataset.i, 1)[0]; const t = [a[0], a[1], 'Just connected', a[2], 1]; T.push(t); const el = row(t); list.appendChild(el); enter(el); count(); menu(); })); }
  menu();
  $('.hnx-test', r).onclick = () => c.run(async () => {
    const rows = [...list.children].filter(el => el._t[4] > 0);
    for (const el of rows){ el.classList.add('chk'); const s = $('.t span', el), was = el._t[2]; swap(s, 'Testing'); await c.wait(420);
      el.classList.remove('chk');
      if (el._t[1] === 'Slack'){ el.classList.add('err'); swap(s, 'Token expired. Reconnect'); }
      else swap(s, was);
    }
    swap(st, rows.length - 1 + ' of ' + rows.length + ' healthy');
    const bad = [...list.children].find(el => el.classList.contains('err'));
    if (bad){ const b = html(`<button class="pill accent sm">Reconnect</button>`); $('.hnx-pm', bad).replaceWith(b); enter(b);
      b.onclick = () => c.run(async () => { b.innerHTML = '<span class="spin"></span>'; await c.wait(800); bad.classList.remove('err'); swap($('.t span', bad), bad._t[2]); const n = row(bad._t); bad.replaceWith(n); enter(n); count(); }); }
  });
});
